import{_ as e,c as a,a2 as r,o as i}from"./chunks/framework.CO0qOYmW.js";const g=JSON.parse('{"title":"AI 工程体系概述","description":"","frontmatter":{},"headers":[],"relativePath":"ai/01-engineering/01-scheme/01-overview.md","filePath":"ai/01-engineering/01-scheme/01-overview.md","lastUpdated":1783608971000}'),o={name:"ai/01-engineering/01-scheme/01-overview.md"};function d(n,t,l,s,h,c){return i(),a("div",null,t[0]||(t[0]=[r('<h1 id="ai-工程体系概述" tabindex="-1">AI 工程体系概述 <a class="header-anchor" href="#ai-工程体系概述" aria-label="Permalink to &quot;AI 工程体系概述&quot;">​</a></h1><p>AI 工程体系关注的是如何把大模型能力稳定、可控、可维护地接入真实业务系统。它不是单点学习某个模型或某个工具，而是从应用形态、架构分层、工程基线、质量治理和生产运营出发，建立一套面向企业落地的 AI 应用方法论。</p><h2 id="核心定位" tabindex="-1">核心定位 <a class="header-anchor" href="#核心定位" aria-label="Permalink to &quot;核心定位&quot;">​</a></h2><ul><li><strong>面向开发者落地</strong>：把模型调用、上下文、知识库、Agent、评测、安全和成本串成完整工程闭环。</li><li><strong>面向企业级架构</strong>：关注多模型接入、权限隔离、审计追踪、稳定性、可观测性和持续迭代。</li><li><strong>面向长期维护</strong>：避免一次性 Demo 思维，让 AI 应用可以被版本管理、测试、发布和运营。</li></ul><h2 id="能力地图" tabindex="-1">能力地图 <a class="header-anchor" href="#能力地图" aria-label="Permalink to &quot;能力地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力域</th><th>说明</th></tr></thead><tbody><tr><td>模型能力</td><td>理解 Token、Embedding、上下文窗口、多模态和推理接口</td></tr><tr><td>工程接入</td><td>封装 SDK、管理密钥、处理重试、限流、超时和降级</td></tr><tr><td>应用构建</td><td>构建 Prompt、RAG、Agent、Copilot、智能问答等应用形态</td></tr><tr><td>生产治理</td><td>建立评测、可观测性、安全合规、成本运营和部署体系</td></tr></tbody></table><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>先建立企业 AI 应用的全局视角，理解 AI 应用和传统应用的架构差异。</li><li>再理解大模型基础能力，明确 Token、Embedding、上下文窗口和推理机制的边界。</li><li>最后建立工程落地基线，把模型能力封装为可复用、可监控、可治理的业务服务。</li></ol>',8)]))}const p=e(o,[["render",d]]);export{g as __pageData,p as default};
